    <script>
        $(document).ready(function() {
            const progressContainer = $(".progress-container");
            const progressBar = $(".progress-bar");
            const statusText = $("#backup-status");

            // Create Backup
            $(".backup-add-btn").on("click", function() {
                if (!confirm("Start a new backup? This may take around 5 minutes.")) return;

                $(this).addClass('d-none');
                progressContainer.show();
                progressBar.css("width", "0%").attr("aria-valuenow", 0).text("0%");
                statusText.text("Backup started... please wait, this may take around 5 minutes.");

                let progress = 0;
                const progressTimer = setInterval(() => {
                    if (progress < 95) {
                        progress += 1; // Simulate progress until near complete
                        progressBar.css("width", progress + "%").attr("aria-valuenow", progress).text(progress + "%");
                    }
                }, 3000); // progress every 3s (~5 min total)

                $.ajax({
                    url: "{{ route('backup.create') }}",
                    method: "POST",
                    headers: {
                        "X-CSRF-TOKEN": "{{ csrf_token() }}"
                    },
                    success: function(response) {
                        clearInterval(progressTimer);
                        progressBar.css("width", "100%").text("100%");
                        statusText.text("Backup completed successfully!");
                        setTimeout(() => progressContainer.fadeOut(), 3000);
                        $(this).removeClass('d-none');
                        // Refresh list
                        loadBackups();
                    },
                    error: function(xhr) {
                        clearInterval(progressTimer);
                        $(this).removeClass('d-none');
                        progressBar.addClass("bg-danger").css("width", "100%").text("Failed");
                        statusText.text("Backup failed: " + (xhr.responseJSON?.message || "Unknown error"));
                    }
                });
            });

